"use client";
import { useState } from "react";
import Formulario from "../components/Formulario";

export default function HomePageView() {
  const [aluno, setAluno] = useState("Samuel");

  return (
    <>
      <h1 className="mb-3">Testes</h1>
      <p className="mb-3">Aluno: {aluno}</p>
      <button
        className="btn btn-primary mb-3"
        type="button"
        onClick={() => setAluno("João")}
      >
        Alterar Aluno
      </button>

      <Formulario />
    </>
  );
}
